import{_ as n,o as a,c as t,a0 as s}from"./chunks/framework.Bogozrur.js";const u=JSON.parse('{"title":"The Intent Engine (v4)","description":"","frontmatter":{},"headers":[],"relativePath":"platform/intent-engine.md","filePath":"platform/intent-engine.md"}'),i={name:"platform/intent-engine.md"};function o(l,e,p,r,d,c){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="the-intent-engine-v4" tabindex="-1">The Intent Engine (v4) <a class="header-anchor" href="#the-intent-engine-v4" aria-label="Permalink to &quot;The Intent Engine (v4)&quot;">​</a></h1><p>AAYU&#39;s crown jewel is its built-in <strong>Native Intent Engine</strong>. AAYU was fundamentally built on the philosophy that human developers should only focus on the <strong>Business Intent</strong>, while the compiler focuses on the <strong>Silicon Execution</strong>.</p><h2 id="intent-to-application" tabindex="-1">Intent to Application <a class="header-anchor" href="#intent-to-application" aria-label="Permalink to &quot;Intent to Application&quot;">​</a></h2><p>Normally, software engineering requires a long translation pipeline: <code>Requirement -&gt; PM -&gt; Systems Architect -&gt; Developer -&gt; Code -&gt; App</code></p><p>AAYU collapses this entirely.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aayu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Build a Police Complaint System&quot;</span></span></code></pre></div><p>When you type an intent like the one above, the <strong>Native Capability Engine</strong> kicks in. It does not ping external AI APIs (OpenAI/Gemini). It natively reasons through the domain using embedded heuristics to infer business structures.</p><h3 id="_1-inferred-roles" tabindex="-1">1. Inferred Roles <a class="header-anchor" href="#_1-inferred-roles" aria-label="Permalink to &quot;1. Inferred Roles&quot;">​</a></h3><p>The Engine identifies who interacts with the system.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>role Citizen.</span></span>
<span class="line"><span>role Officer.</span></span>
<span class="line"><span>role Admin.</span></span></code></pre></div><h3 id="_2-inferred-entities" tabindex="-1">2. Inferred Entities <a class="header-anchor" href="#_2-inferred-entities" aria-label="Permalink to &quot;2. Inferred Entities&quot;">​</a></h3><p>The Engine extracts what data objects must exist.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>entity Complaint.</span></span>
<span class="line"><span>    text description.</span></span>
<span class="line"><span>end.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>entity Evidence.</span></span>
<span class="line"><span>    text file_path.</span></span>
<span class="line"><span>end.</span></span></code></pre></div><h3 id="_3-inferred-relations" tabindex="-1">3. Inferred Relations <a class="header-anchor" href="#_3-inferred-relations" aria-label="Permalink to &quot;3. Inferred Relations&quot;">​</a></h3><p>The Engine constructs the relational database bindings.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>relation Complaint one_to_many Evidence.</span></span>
<span class="line"><span>relation Citizen one_to_many Complaint.</span></span></code></pre></div><h3 id="_4-inferred-workflows" tabindex="-1">4. Inferred Workflows <a class="header-anchor" href="#_4-inferred-workflows" aria-label="Permalink to &quot;4. Inferred Workflows&quot;">​</a></h3><p>The Engine calculates the exact state machine pipeline required for the domain.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>workflow InvestigationWorkflow for Complaint.</span></span>
<span class="line"><span>    step Filed.</span></span>
<span class="line"><span>    step Investigating.</span></span>
<span class="line"><span>    step Closed.</span></span>
<span class="line"><span>end.</span></span></code></pre></div><h2 id="the-final-output" tabindex="-1">The Final Output <a class="header-anchor" href="#the-final-output" aria-label="Permalink to &quot;The Final Output&quot;">​</a></h2><p>AAYU automatically writes all of this into a pristine, ready-to-run <code>main.aayu</code> file, alongside dynamically generated UI <code>crud</code> components.</p><p>You go from a single English sentence directly to a full-stack, secure, role-based application in <strong>less than 10 seconds.</strong></p><p>Welcome to the Intent Operating System.</p>`,23)])])}const g=n(i,[["render",o]]);export{u as __pageData,g as default};
